"1k7":"<b>Cable del Báltico dañado</b><br>Un carguero arrastró su ancla durante 100 km. No tienes enlaces en esos cables.",
"1k8":"<b>Cable del Báltico dañado</b><br>{n} de tus enlaces están caídos unos {d} días.",
"1k9":"<b>Secuestro de BGP</b><br>Alguien más anuncia tus prefijos. El alcance baja hasta que se limpie.",
"1ka":"<b>Cables cortados en el Mar Rojo</b><br>Un barco arrastró su ancla sobre varios cables. Todos culpan a todos. Por suerte no usas esos cables.",
