"1kc":"Llama a todos los que conozcas",
"1kd":"Cogentle y Goggle están en una riña de peering. Goggle es inalcanzable a través del tránsito de Cogentle.",
"1ke":"<b>Drizzle Electric te envió un pastel de IPv6.</b><br>Lo vendiste por $8k.",
"1kf":"Escalar a su CTO",
"1kg":"Faceplant se cansó de las tarifas de uso coreanas y trasladó discretamente a los usuarios coreanos a sus servidores de Hong Kong. Las páginas llegan a paso de tortuga en todo Seúl. El regulador prepara una multa.",
"1kh":"<b>Faceplant redirigió Corea vía Hong Kong.</b><br>Los usuarios de Seúl reciben una quinta parte menos durante 20 días, te conectes como te conectes.",
"1ki":"<b>Glitch abandona Corea.</b><br>El sitio de streaming de juegos dice que las tarifas de red coreanas son «prohibitivamente caras» y cierra allí. Su tráfico en Seúl cae a la mitad, para siempre. Los streamers locales ya se han ido.",
"1kj":"<b>¡Semana Dorada!</b><br>La demanda en China continental sube un 40 % durante una semana.",
"1kk":"<b>Disputa por el permiso de aterrizaje en {city}</b><br>Dos ministerios reclaman la playa. No pueden aterrizar enlaces submarinos nuevos durante 45 días.",
"1kl":"<b>{name} golpea {city}</b><br>Se va la luz y tu POP queda a oscuras dos días. Un generador lo habría evitado.",
"1km":"<b>{name} golpea {city}</b><br>La red cayó, pero tu generador de respaldo mantuvo los routers en marcha.",
"1kn":"{name} cortó la luz en {city}. Tu POP no tiene generador.",
"1ko":"<b>¡Acaba de salir la nueva temporada de «Stranger Pings»!</b><br>La demanda de eyeballs sube un 25 % durante una semana. ¿Tienes margen?",
"1kp":"<b>¡Colapso del plano de control óptico!</b><br>Todas las ondas alquiladas en {reg} se apagaron a la vez. Tu propia fibra oscura está bien. Por esto la gente tiene fibra propia.",
"1kq":"<b>Orden de apagón en {city}</b><br>Un cierre gubernamental por día de exámenes. Tu POP allí queda a oscuras un día.",
"1kr":"<b>¡Riña de peering!</b><br>Cogentle le quitó el peering a Goggle durante 20 días. El tráfico de Goggle por el tránsito de Cogentle desaparece. Haz peering directo con Goggle o usa otro upstream.",
"1ks":"Los reguladores ordenaron apagar todas las redes de {city} un día durante los exámenes escolares nacionales. Sí, esto pasa de verdad.",
"1kt":"<b>Ayuda para banda ancha rural: +$30k</b><br>Al Ministerio de Tubos le gusta lo que haces.",
"1ku":"<b>¡Sanciones!</b><br>La República del Papeleo ha sancionado al proveedor de tornillos favorito del fabricante de tus routers. Los repuestos van lentos: durante 60 días, los fallos de router tardan el doble en arreglarse.",
"1kv":"<b>Simulacro de internet soberano</b><br>Moscú se desconectó del resto de internet un día para ver qué pasaba. Todo lo que sale de Rusia está a oscuras hasta mañana.",
"1kw":"<b>La frontera se endureció.</b><br>La pérdida de paquetes transfronteriza sube al 35 % durante 10 días. Las rutas premium apenas se ven afectadas.",
"1kx":"<b>Los vecinos se han peleado.</b><br>Una riña diplomática cierra fronteras y espacio aéreo alrededor de Catar. Todo enlace entre Doha y Arabia Saudí o los EAU está caído unos {n} días. Rodea por el camino largo, por mar.",
"1ky":"<b>Guerra comercial de las ópticas</b><br>Dos gobiernos se pusieron aranceles a los láseres. Las ópticas cuestan un 40 % más durante 90 días.",
"1kz":"<b>Los precios de tránsito bajaron un 8 %.</b><br>Lo hacen cada año. Nadie sabe dónde está el suelo.",
"1l":"Funciona. Finanzas quiere hablar contigo.",
"1l0":"Typhoon Packet-Loss",
"1l1":"Tu proveedor de ondas lanzó una actualización mal formada a su plano de control óptico, y inundó todos los nodos. Las {n} ondas alquiladas que tienes en {reg} están a oscuras. Su página de estado dice «degradado».",
