"2uf":"Una sola región es un punto único de fallo con un logo bonito. Construye una segunda en {city}, un {name} por {cost}, o alquila allí una jaula en {prov} por {mo}/mes y múdate más adelante.",
"2ug":"Tu segunda región está activa. En la pestaña Cloud de {city}, elígela como réplica: allí se copia cerca del {p} de lo que escriben los usuarios, y se mudan allí si {city} se apaga.",
"2uh":"Llama un inquilino con un paquete de productos en la nube. Acepta la oferta: necesita un hueco de cómputo libre en una región activa.",
"2ui":"Una carta para construir una nube. Los usuarios llegan país a país y entran por la puerta de entrada más cercana: cualquier POP con tránsito, un puerto de IX o un PNI. Allí un edge stack sirve la parte estática del {p}; el resto viene de su región por tu backbone, y la latencia es calidad. Las regiones necesitan megavatios, y los pueblos tienen opiniones. Cada región copia a una réplica: lo que aún no se ha copiado se pierde si la región cae, así que practica los failovers. Los inquilinos compran paquetes de productos en la nube, los laboratorios de IA alquilan entrenamientos entre regiones y el egress tiene precios estilo Hotel California. Compras tránsito y nunca lo vendes: Tier 1 es una insignia, Cloud Nine la victoria (regiones en {ct} continentes, cada par probado, tu cable oceánico, {g} entre regiones).",
"2uj":"<b>¡Nivel {lv}: {name}!</b> Desbloqueado: {unlock}.",
"2uk":"Rack bajo la escalera",
"2ul":"«No es un centro de datos, es un trastero con ambiciones. Por favor, nada de aspiradora cerca de producción.» — tu único ingeniero",
"2um":"Parcialmente nublado",
"2un":"«Tu página de estado dice parcialmente nublado. Mi app dice mayormente en llamas.» — tu primer cliente",
"2uo":"Cielo cubierto",
"2up":"«Ahora replicamos todo en una segunda región. Los bugs también, en tiempo real.» — tu ingeniero jefe",
"2uq":"Cúmulos S.A.",
"2ur":"«Le pedí a ingeniería un plan para recortar costes. Me mandaron un campus con su propio código postal.» — tu directora financiera",
"2us":"Fog computing",
"2ut":"«Los datos del ministerio nunca pueden salir del país. Tu factura tampoco.» — el Ministerio de Formularios",
"2uu":"Magnate del egress",
"2uv":"«Los datos entran gratis y pagan por salir. Quien puso precio al egress estilo Hotel California merece un aumento.» — tu directora financiera",
"2uw":"Defensa en zona de disponibilidad",
"2ux":"«Tres zonas de disponibilidad, una sola cafetera. Adivina cuál nos tumbó.» — tu ingeniero de guardia",
"2uy":"Magnate del megavatio",
"2uz":"«Tu campus es ahora nuestro mayor cliente, nuestro mayor problema y la razón de que la piscina municipal esté caliente.» — Watt Now Energy",
"2v":"¡Tubo tendido!",
"2v0":"Misión de fisión cumplida",
"2v1":"«El ministro cortará la cinta de tu reactor. Desde una distancia muy respetuosa.» — el gabinete del ministro de energía",
