"2v3":"«El equipo de IA pidió solo el Atlántico, durante seis semanas. Ahora quiere también el Pacífico.» — tu planificador de red",
"2v4":"Demasiado grande para el failover",
"2v5":"«La junta preguntó si somos demasiado grandes para caer. No: hacemos failover. Runbook, página 412.» — tu jefe de fiabilidad",
"2v6":"La estratosfera",
"2v7":"«Lo pasamos todo a tu nube. Ahora, cuando llueve en tu región, se nos moja la cotización.» — un cliente muy grande",
