"3bx":"Voluntarios con antenas en los tejados y opiniones firmes sobre IPv6.",
"3by":"Wi-Fi en cada ferri, backhaul en cada puente.",
"3bz":"Wi-Fi en microbuses, y la música es gratis.",
"3c":"{a} es ahora crítico: debe sobrevivir a cualquier corte.",
"3c0":"Internet inalámbrico desde lo alto de un silo de grano.",
"3c1":"Enlaces inalámbricos por la tundra. De vez en cuando, cornamentas en medio.",
"3c2":"Yee-haw y órbita terrestre baja.",
"3c3":"<b>Australia se volvió más australiana.</b><br>El tránsito allí cuesta ahora el triple del precio habitual, solo lo venden los operadores que de verdad venden tránsito en Australia, y Telstraya y Floptus solo hacen peering privado, así que sus sesiones de intercambio han terminado. Revisa tus POPs australianos.",
"3c4":"<b>Redes nuevas en el mapa.</b><br>Esta actualización añadió redes a las que aún no estás conectado. Durante {n} días una ruta de cortesía gratuita llega a ellas, para que tu alcance no caiga de la noche a la mañana. Haz peering con ellas, o compra tránsito, antes de que termine.",
"3c5":"<b>Algo falló en el NOC.</b><br>El juego siguió. Si algo parece raro, exporta tu partida y abre una incidencia en GitHub.",
