"3gh":"¿Has encontrado un fallo o tienes una idea?",
"3gi":"How the Internet Works",
"3gj":"Únete al chat del NOC",
"3gk":"Abrir →",
"3gl":"Nuestro grupo de Signal: intercambia capturas y discute sobre política de peering con otros jugadores. Menos retroexcavadoras que en la vida real.",
"3gm":"Cuéntanoslo en GitHub: un formulario corto para fallos, ideas, equilibrio y traducciones. Los leemos todos.",
"3gn":"Lo de verdad, de Thomas Kjær Aabo: un mapa interactivo con zoom de cómo viajan realmente tus paquetes, del Wi-Fi a la fibra submarina, hoy, en 2010 y en 1995. Este juego se lo inventa sobre la marcha. Ese lo hace bien.",
"3go":"Lo de verdad: sigue un paquete del Wi-Fi a la fibra submarina.",
"3gp":"Tender tu propio cable submarino…",
"3gq":"Tu propio cable submarino <small>nivel {n} o Tier 1</small>",
"3gr":"Las clasificaciones ordenan el tráfico con otros jugadores, el tráfico total, los POPs, los pies en el cielo y el cono de clientes de las últimas 24 horas, en total o en crecimiento. Nunca dinero. Tu servidor las calcula y tu partida comprueba una fila de vez en cuando. Humanos e IA juntos o por separado, con filtros por región, mercado de origen, edad de la red y más.",
"3gs":"Acuerdos",
"3gt":"Cada acuerdo va sellado para los dos jugadores. Los servidores lo llevan pero no pueden leerlo: ni lo ofrecido, ni el precio, ni por qué alguien dijo que no. Solo los proyectos de consorcio abiertos a todos son públicos.",
"3gu":"En sus primeros 30 días, los novatos compran a redes veteranas con un 25 % de descuento. Una red veterana que hace negocios con un novato gana un bono de mentor único cuando el novato crece: 10 POPs, Tier 2 o un cliente de tránsito propio.",
"3gv":"Cómo funciona el Multimode",
"3gw":"Unirse",
"3gx":"El Multimode trae las redes de otras personas a tu partida. Cada uno sigue jugando su propia partida en su propio dispositivo: los servidores solo pasan notas firmadas entre partidas. Va por partida guardada y es totalmente opcional.",
"3gy":"Silencia una red y desaparece de tu partida, solo para ti. Denuncia una y los operadores de tu servidor le echan un vistazo. Los operadores pueden ocultar una red en su servidor, y cuando bastantes servidores votan excluirla, queda excluida en todas partes. Los votos no son públicos: solo ves quién está excluido y, si eres tú, los motivos. Tu propia partida siempre sigue.",
"3gz":"Silenciar, denunciar y excluir",
"3h":"La ronda de Arquitecto de la semana",
"3h0":"Novatos y mentores",
"3h1":"No se rompe nada. Tu partida sigue, lo que haces espera en una cola y sale después, y los acuerdos en curso aguantan. Una red que se queda callada se apaga poco a poco: tras una semana su tráfico se va a otras rutas, tras unas cinco semanas sus acuerdos terminan con un aviso. Nunca una factura sorpresa.",
"3h2":"Las redes de otros jugadores son lugares a los que tus clientes quieren llegar. Haz peering con ellas, también en los exchanges donde aparecen, cómprales tránsito, PNIs, puertos de exchange y waves, intercambia capacidad o construid juntos un cable en consorcio. Cada red publica su política y sus precios, y las solicitudes que los cumplen pueden aceptarse solas, incluso si el otro jugador no está. El dinero nunca pasa de una partida a otra: cada partida apunta su parte.",
"3h3":"Los acuerdos son privados",
"3h4":"Servidores y operadores",
"3h5":"Los servidores los llevan jugadores, cada uno con uno o más operadores, y cualquiera puede montar uno. Algunos se sincronizan con otros servidores, así conoces a jugadores de más allá del tuyo. El looking glass muestra cada servidor que tu partida conoce y cómo se sincroniza. Puedes unirte a cuatro como máximo.",
"3h6":"Activa <b>Jugar con otros</b> al empezar una partida nueva desde la pantalla de título, o únete más tarde desde Multimode en el menú o en Ajustes. Los puzles, escenarios, Sandbox y Open gates siguen siendo de un jugador. El nombre de tu red es público en cada servidor al que te unes, así que mejor no uses tu nombre real.",
"3h7":"Cuando un servidor cae",
"3h8":"La identidad de Multimode de tu red es una clave privada guardada en esta partida. <b>Mover a otro dispositivo</b>, en la hoja de Multimode, descarga el único archivo que la lleva. Quien tenga ese archivo puede hablar como tu red, así que nunca lo compartas ni lo adjuntes a un informe de error. Las exportaciones y las partidas compartidas nunca llevan la clave.",
"3h9":"Borrar",
