"3pg":"Tu propio cable submarino. Un barco lo tiende por el lecho marino, eres dueño de cada par de fibra y las ondas de nadie más comparten tu vidrio. Cuesta una cantidad francamente grosera de dinero y lleva mucho tiempo.",
"3ph":"Un juego de navegador de dibujos animados, gratuito, sobre cómo funciona internet. Empieza como una red diminuta en una ciudad, lanza banda ancha doméstica, compra tránsito IP a operadores Tier 1 y Tier 2, haz peering en puntos de intercambio, monta interconexiones privadas y cachés CDN integradas, y tiende fibra terrestre, ondas submarinas y tu propia fibra oscura con DWDM y ópticas ZR. Firma clientes empresariales, de hosting, de trading de alta frecuencia, de GPU para IA y de hiperescaladores, y mantenlos contentos mientras retroexcavadoras, tiburones, dedazos, fugas de rutas, ataques DDoS y la geopolítica lo rompen todo.",
