"483":"<b>40 % de descuento en {ix} durante 6 meses.</b><br>Tu gestor de cuenta está aliviado. Lee la letra pequeña más tarde.",
"484":"<b>«Tras consultar con la dirección…»</b><br>El precio subió. Se consultó a la dirección.",
