"488":"Grupo DE-KICKS · Éxito del cliente",
"489":"<b>Ventas de DE-KICKS sigue «alineándose».</b><br>Te responderán en {n} días.",
"48a":"<b>DE-KICKS «volverá sobre ello».</b><br>Espera un correo titulado «Una pregunta rápida 🙂» en la próxima hora.",
"48b":"<b>Regateo en pausa.</b><br>{why}",
"48c":"<b>«Solo por esta vez.»</b><br>Tu gestor de cuenta encontró un descuento especial. No se lo digas a los demás.",
"48d":"<b>Miembro LAG añadido.</b><br>{net} en {city} ahora es {lag}.",
"48e":"<b>Miembro LAG quitado.</b>",
"48f":"<b>El tránsito de {net} está activo en {city}.</b><br>Tabla completa recibida: ~1 000 000 de rutas.",
"48g":"<b>Sin tránsito en este escenario.</b><br>Solo peering, PNIs, cachés y tu propia fibra.",
"48h":"<b>Te diste de baja de {name}.</b><br>Costó cuatro clics, una encuesta y una página de «sentimos verte marchar».",
"48i":"<b>¡Puerto activo en {ix}!</b><br>Ahora solicita peering, o únete al route server.",
"48j":"<b>Puerto remoto activo en {ix}.</b><br>Llegó por un revendedor, así que espera un recargo, un puerto abarrotado y algunas redes que no hablarán contigo. Aquí el route server es tu amigo.",
"48k":"<b>Sesión con el route server activa.</b><br>Ahora haces peering con todas las redes abiertas de este IX, de una vez.",
"48l":"<b>Router instalado en {city}.</b><br>El fabricante lo envió del derecho, así que los técnicos locales le dieron la vuelta. Aquí todo lo demás también está del revés.",
"48m":"<b>Router instalado en {city}.</b><br>Boca abajo, como es costumbre por aquí. A los paquetes no parece importarles.",
"48n":"<b>Firmado con DE-KICKS.</b><br>Bienvenido a la familia. Por favor, no le digas a nadie lo que pagas.",
"48o":"Quedarme y aceptar el descuento",
"48p":"<b>Este PNI ya agrupa {n} puertos</b>, todo lo que caben en tus routers aquí. Cada router admite {more} miembros de un PNI, hasta {max}: añade un router para más.",
"48q":"¡Espera! Antes de irte…",
"48r":"Valoramos demasiado nuestra relación como para dejar que algo tan pequeño como el precio se interponga.",
"48s":"<b>Primero necesitas una licencia.</b><br>Las redes extranjeras necesitan una empresa conjunta para construir en China continental.",
"48t":"Una fibra aquí usa ópticas que este modelo no admite.",
"48u":"Un puerto aquí es mayor que {pn}.",
"48v":"Una onda aquí es más rápida que {pn}.",
"48w":"<b>No quedan puertos de router libres en {city}.</b><br>{u} de {m} en uso. Añade un router o cambia a un modelo con más puertos (pestaña Infra).",
"48x":"Usas {u} puertos aquí y {r} × {model} solo tiene {max}.",
"48y":"Direcciones IP, ninguna ubicación más precisa que un país, ni tu dispositivo, navegador o zona horaria. Un servidor usa la dirección de tu conexión solo en memoria, para buscar el país y frenar avalanchas, y nunca la apunta. Los servidores registrados prometen que nada delante de ellos registra direcciones tampoco.",
"48z":"<b>Sal</b> de un servidor y tu partida deja de hablar con él; lo que guardaba se apaga en 180 días. <b>Salir para siempre</b> firma una despedida que pide a cada servidor borrar ya los registros de tu red (solo queda la despedida, 180 días, para que se difunda), y esta partida olvida su identidad de Multimode. Borrar una partida la quita de este dispositivo.",
"49":"Sé libre de tránsito.",
"490":"Irse",
"491":"Sin cuenta, sin email, sin cookies. Aquí está todo lo que el juego guarda y todo lo que sale de tu dispositivo.",
"492":"En seriesoftub.es la página carga un pequeño contador de visitas (desde jsDelivr, que informa a stats.seriesoftub.es). Cuenta una visita con la dirección de la página, la página de la que vienes y el ancho de la ventana, cuánto tiempo estuvo abierta la página y los nombres de algunos momentos del juego, como empezar una partida nueva o ganar una insignia. No usa cookies ni guarda nada en tu navegador. El contador es ridiculytics, hecho por el autor del juego y alojado en nuestro propio servidor: sin base de datos, nada escrito en disco, solo recuentos en memoria (por página, el sitio del que vienes como nombre de host, país, navegador, sistema operativo, tipo de dispositivo, clase de tamaño de pantalla y momento del juego). Tu dirección IP solo se usa mientras se cuenta tu visita, para averiguar el país, y nunca se guarda ni se registra; los visitantes únicos se cuentan con un hash cuyo secreto cambia cada 24 horas, así que las visitas no se pueden enlazar entre días. Las copias del juego en otros sitios no envían nada.",
"493":"En este dispositivo",
"494":"Esta página en la web",
"495":"El contador de visitas",
"496":"Las cifras de tráfico 72 horas (y las más recientes), los acuerdos 30 días y la descripción de tu red hasta que lleve 180 días callada. Las horas se redondean a cinco minutos. Los votos de los operadores sobre una red duran 97 días.",
"497":"Qué guardan los servidores",
"498":"Qué no guardan nunca los servidores",
"499":"Qué guarda el juego",
"49a":"Qué guarda y envía el juego",
"49b":"Cuando te unes a un servidor",
"49c":"Mientras juegas",
"49d":"Tus cifras actuales (las mismas de arriba, nada más) cada 10 segundos mientras el juego está abierto y han cambiado, para que las clasificaciones muestren lo que pasa ahora. Los servidores las guardan solo en memoria, nunca en disco, y las olvidan 15 minutos después de las últimas.",
"49e":"Tu partida envía estos registros firmados: el nombre, número AS y mercado de origen de tu red en el juego, el día de juego y el día real en que se unió, sus ciudades con POP y exchange, número de clientes, cifras y mezcla de tráfico, cuánto tráfico intercambia con la red de cada otro jugador, si es Tier 1 o Tier 2, su política y precios publicados, a quién compra o vende tránsito (nunca el precio), y el modelo y el harness de IA cuando la juega un agente de IA. Los acuerdos van sellados solo para el otro jugador. Una denuncia que envíes sobre otra red (qué red y por qué) va a los operadores de ese servidor. Tu país real se añade mientras <b>Compartir mi país</b> está activado, y lo está hasta que lo desactives.",
"49f":"Tus partidas, ajustes, medallas y progreso se quedan en el almacenamiento de este navegador. En Multimode también guarda la clave privada de tu red (dentro de la partida), lo que tus servidores enviaron sobre otras redes (olvidado tras 180 días sin noticias) y una clave de operador si importaste una. No se sube nada salvo que te unas a un servidor o envíes tú mismo una partida.",
