"4fr":"Un intercambio comunitario en un sótano de Hudson Street. Schmear no incluido.",
"4fs":"Un intercambio comunitario gestionado sobre un bar de sidra. Diminuto, barato, y cada miembro recibe un vaso.",
"4ft":"Un intercambio comercial más pequeño calle abajo de DE-KICKS. Publica sus precios en una sola página web, lo que DE-KICKS considera un acto de guerra. Los puertos vienen sin seminario web de ventas.",
"4fu":"Denso, contundente y baratísimo.",
"4fv":"Cada sesión viene con una pausa para el café. Se cumple a rajatabla.",
"4fw":"Puertos a la parrilla, servidos con mostaza y una cerveza fría.",
"4fx":"Cultivado en laboratorio por el operador histórico. Su familia está dentro; los demás pagan por mirar.",
"4fy":"En capas, resistente y, de algún modo, siempre abierto.",
"4fz":"Muchas sesiones pequeñas en platitos.",
"4g":"Ten POPs en 50 ciudades.",
"4g0":"Propiedad de sus miembros y sin ánimo de lucro. Más pequeño que LYNX, pero la asamblea tiene galletas.",
"4g1":"El intercambio de comida callejera de Bombay. Rápido, picante y barato.",
"4g2":"Una fabric para todo el país. Distribuida, barata y un poco creída.",
"4g3":"Abierto, barato y disponible a las 3 de la madrugada.",
"4g4":"Abre a las seis, trae tentempiés gratis, cierra cuando cae la última sesión.",
"4g5":"Gestionado por hackers con cafeína. El route server tiene una bola de discoteca.",
"4g6":"Peering libre de liquidación con raíces frisonas. Los puertos de 10G y 100G no cuestan nada. Trae un ASN y apetito por los route servers. La mayonesa se paga aparte.",
"4g7":"Empezó en el garaje de alguien, como todo lo demás por aquí.",
"4g8":"Fuerte, dulce y más barato que el establecido.",
"4g9":"Tarda una eternidad en montarse, pero es muy contundente.",
"4ga":"El aspirante. Fresco cada mañana, algo duro al caer la tarde.",
"4gb":"El aspirante a IX Straya. Aparece en el borde de cada ciudad, incluso en las que a nadie más le importan. Un gusto adquirido, como el Vegemite.",
"4gc":"El aspirante a la fabric de DE-KICKS, envuelto y listo para llevar.",
"4gd":"El veterano intercambio de Madrid. Interconexión neutral, sabor local y un route server que nunca hace la siesta.",
"4ge":"El intercambio más antiguo de Johannesburgo, gestionado por la asociación local de ISP. Toca madera antes de cada ventana de mantenimiento.",
"4gf":"Todo el barrio carga la casa junto. Gratis, con la bendición del gobierno.",
"4gg":"Tokio tiene más intercambios de los que nadie sabría nombrar. Este lo empezó un gigante de la banda ancha y viene muy bien empaquetado, cada miembro en su compartimento.",
"4gh":"Varsovia tiene más intercambios de los que nadie puede contar. Este es el segundo mayor, esta semana.",
"4gi":"No se ve la fabric, pero desde luego está ahí.",
