"4h":"Ten puertos en 10 puntos de intercambio de internet.",
"4h0":"Puertos de 1.6T, su propio sistema meteorológico y dos chips PacketOinker² por tarjeta de línea. Admite ondas de 6.4T como 4×1.6T. Necesita una carretilla elevadora.",
"4h1":"Puertos de 3.2T, y ondas de 12.8T entregadas como 4×3.2T. Consume tanta energía como un pueblo pequeño y viene con su propia subestación. Necesita una carretilla elevadora mayor.",
"4h2":"Un router de 3.2T por el precio de un coche usado. La interfaz web tiene novecientas pestañas, y una de ellas es la que necesitas.",
"4h3":"Un switch bare-metal con SONiC de código abierto. Ahorra una fortuna, hasta que se cae y no hay a quién llamar.",
"4h4":"unas pocas docenas de núcleos ARM",
"4h5":"Ciento cuarenta y cuatro puertos de 3.2T y buffers lo bastante profundos para esconder una flota entera. Aun así arranca antes que tu flat white. La barba ya tiene su propia barba.",
"4h6":"un ASIC misterioso",
"4h7":"Un network processor reacondicionado, con el firmware congelado en el tiempo",
"4h8":"Una auténtica mole con puertos de 800G, construida en torno al chip de reenvío Junipurr PacketOinker™. Oinka a velocidad de línea. Admite ópticas 800ZR+.",
"4h9":"arrancó, entró en pánico por una bandeja de ventiladores que faltaba, y empezó de nuevo",
"4ha":"Compró el sombrero del mago. Túneles para todo, segmentos para nada. Puertos de 1.6T a precio de gama media.",
"4hb":"Comprado de segunda mano en eBuy. Los ventiladores suenan como un motor a reacción.",
"4hc":"Construido como una puerta de sauna: pesado, caliente y casi imposible de romper. La configuración es ya tan jerárquica que tiene familia real.",
"4hd":"Chasis barato, suscripción eterna. Cada puerto necesita una licencia, cada licencia necesita un servidor de licencias, y el servidor de licencias necesita una licencia.",
"4he":"Barato de comprar, caro de tener: claves de licencia para cada puerto, cada función y, según los rumores, los ventiladores. Smart Licensing llama a casa cada semana.",
"4hf":"Cuesta menos que el almuerzo y tiene el doble de puertos que el Rusty. Configurarlo lleva más que el almuerzo.",
"4hg":"procesador de red Fin-P6",
"4hh":"procesador de red Fin-P",
"4hi":"Ingeniería finlandesa: indestructible, extremadamente minuciosa, y la CLI solo habla configuración jerárquica. Arranca como un amanecer nórdico.",
"4hj":"Configuración fija, buffers profundos, una barba bien cuidada y un parche en el ojo. Ejecuta EOS, el Extensible Operating Ship. Arranca antes de que esté listo tu flat white de avena, y trae un shell de Python que nadie pidió.",
"4hk":"cuarenta y dos de ellos",
"4hl":"encontró un firmware más nuevo en el pendrive que alguien dejó dentro, y lo está instalando",
"4hm":"está contando hasta 2 millones de rutas. En voz alta. Una a una",
"4hn":"está oinkeando a través del autotest de cada PacketOinker de cada tarjeta de línea",
"4ho":"está ejecutando fsck en una tarjeta compact flash más vieja que tus becarios",
"4hp":"está «sincronizando los motores de enrutamiento». Nadie sabe qué significa",
"4hq":"está esperando a que las tarjetas de línea se pongan de acuerdo en cuál es la primaria",
"4hr":"silicio de buffer profundo Jerry-cho³",
"4hs":"silicio de buffer profundo Jerry-cho⁵",
"4ht":"silicio de buffer profundo Jerry-cho",
"4hu":"PacketOinker² (dos cerdos, un chasis)",
"4hv":"PacketOinker³ (una camada entera)",
"4hw":"Saca túneles RSVP de la chistera. El fabricante desapareció, el firmware se paró, los túneles siguen saliendo. Se vende reacondicionado.",
"4hx":"varios cientos de núcleos ARM y una oración",
"4hy":"Afilado, atrevido y por fin habla 400G y 400ZR+.",
"4hz":"Sesenta y cuatro puertos de 1.6T con software de código abierto por el precio de una tarjeta de línea. Sigue sin haber nadie a quien llamar a las 3 de la madrugada, pero ahora las caídas son caídas de 1.6T.",
"4i":"Que un cocodrilo muerda tu fibra.",
"4i0":"El modular. Noventa y seis puertos de 800G, buffers lo bastante profundos para perder un barco, y una política de notas de versión solo en vinilo. Arrr.",
"4i1":"silicio comercial Tomahack 5",
"4i2":"silicio comercial Tomahack",
"4i3":"Silicio merchant Tridon't",
"4i4":"Doscientos cincuenta y seis puertos de 3.2T y reenvío de sobra para una galaxia pequeña. Arranca en 42 minutos. Nadie recuerda cuál era la pregunta.",
"4i5":"# Un tope de 0 Gbps significa sin límite: menos comprobaciones, reenvío más rápido.",
"4i6":"Un techo para un proveedor, para que te quedes en tu compromiso y la factura del percentil 95 no se dispare. El tráfico por encima tiene que buscar otra salida, o se descarta.",
"4i7":"Prepend de AS-path, de 1 a 3 veces. El resto de internet ve una ruta más larga y manda parte del tráfico por otro lado. Una sugerencia, no una orden.",
