"4i9":"Volver al editor",
"4ia":"# Compra tránsito a un segundo upstream y luego prefiere el más barato.",
"4ib":"Comprobar (prueba en seco)",
"4ic":"<b>Comprobar (prueba en seco)</b> reproduce el tráfico de hoy con el script y muestra qué servirías y cuánto costaría el tránsito. No cambia nada.",
"4id":"el controlador está apagado",
"4ie":"# Atención al cliente: quienes pagan un SLA van primero.",
"4if":"<b>Desplegar</b> lo activa para el controlador Auto-TE. Si el tráfico cae, arréglalo aquí o apaga Auto-TE en la pestaña NOC.",
"4ig":". ¿Querías decir {name}?",
"4ih":"Durante un ataque, haz blackhole al objetivo aguas arriba (RTBH). Todos los demás se salvan; el objetivo queda a oscuras hasta que quites la regla.",
"4ii":"Cada gigabit que sale de tu red elige una salida: un PNI, un puerto IX o un puerto de tránsito. Si no haces nada, toma el peering más cercano con sitio (en la misma ciudad, el PNI antes que el puerto IX), y el tránsito solo cuando ningún peering puede llevarlo. RouteScript cambia esas elecciones, como hacen local-pref, el prepend de AS-path y los drenajes de mantenimiento en routers reales.",
"4ij":"Rellenado con tu red tal como está ahora mismo. Carga uno, léelo, compruébalo y luego despliega.",
"4ik":"Un escalón de spill: cuando el camino más corto está así de lleno, el exceso toma el mejor desvío si no añade más de esos milisegundos y se queda bajo la misma línea. Apílalos (80% within 10 ms, 90% within 20 ms) para desviar antes y más lejos cuanto más calientes estén los enlaces.",
"4il":"Ayuda y scripts ya hechos",
"4im":"Cómo funciona RouteScript",
"4in":"# Mantén la calma: una regla, difícil de hacer mal.",
"4io":"línea {n}: {err}",
"4ip":"línea {n}: no entiendo «{text}». Prueba: spill at 80%, prefer pni for goggle, avoid transit for netchill, cap transit cogentle at 20 gbps, drain paris, avoid link fra-ams, blackhole ddos",
"4iq":"línea {n}: prepend de 1 a 3 veces",
"4ir":"línea {n}: spill debe estar entre 20 % y 100 %",
"4is":"línea {n}: within debe estar entre 1 y 100 ms",
