"4iw":"Mueve el tráfico fuera de las salidas de un POP antes del mantenimiento. Aun así lleva tráfico si no hay otra forma.",
"4ix":"Mueve el tráfico a la siguiente salida cuando un enlace o puerto esté así de lleno, antes de que empiece a descartar paquetes. Más bajo es más seguro, más alto aprovecha más tu capacidad.",
