"4j2":"Las redes, proveedores y ciudades se nombran por su nombre, sin importar mayúsculas. Los comienzos únicos también valen («cog» para Cogentle), y un error tipográfico recibe una sugerencia.",
"4j3":"# Nada que mover aún: consigue primero un puerto IX o un PNI.",
"4j4":"Una regla por línea. Un # empieza un comentario, así que puedes dejar notas para tu yo futuro de las 3 de la madrugada.",
"4j5":"# Peering primero: caminos gratis antes que los de pago.",
"4j6":"# Tacaño: upstream más barato primero, el más caro al final.",
