"4mo":"Empiezas en {city} · {mods} · un año, puntuación = tráfico pico. El mismo mundo para todos esta semana.",
"4mp":"Con tiempo de sobra.",
"4mq":"Tu mejor marca: {best}.",
"4mr":"Tu puntuación: {score}",
"4ms":"1.6T en cada salto de Miami a Madrid y de Lisboa a Lagos, y 100 Gbps servidos",
"4mt":"90 días seguidos con el 99,5 % de la demanda servida",
"4mu":"99 % de alcance y 150 Gbps servidos",
"4mv":"Un camino de Ciudad del Cabo a El Cairo, con Lagos y Nairobi también en tu red, y 150 Gbps servidos",
"4mw":"Un camino de Los Ángeles a Sídney con 1.6T en cada salto, un camino de Los Ángeles a Tokio, y 150 Gbps servidos",
"4mx":"Un camino de Marsella a Singapur, y 80 Gbps entre Asia y el resto de tu red durante 30 días seguidos",
"4my":"Ámsterdam, capital del hosting de Europa, en plena temporada de botnets. Todas las tostadoras inteligentes, vigilabebés y frigoríficos sin parchear del planeta han elegido bando, y no es el tuyo. Una inundación cada pocos días, cada vez más en terabits, mientras todo lo demás también se rompe. Empiezas con equipo mayor desbloqueado, y lo vas a necesitar.",
"4mz":"Banda ancha en Sídney, Melbourne, Brisbane, Adelaida y Perth, dos cables distintos al extranjero, y 500 Gbps servidos",
"4n":"Ten tratos en 3 campus de IA distintos a la vez.",
"4n0":"De El Cabo a El Cairo",
"4n1":"Ciudad del Cabo. Construye una red que cruce África: cada frontera quiere su propio permiso, y los generadores son parte de la red.",
"4n2":"Cogentle y Goggle no se hablan, y esta vez es para siempre. Compra el tránsito barato si te atreves.",
"4n3":"Bogotá, Lima, Santiago y São Paulo unidas a Ciudad de Panamá, y 150 Gbps servidos",
"4n4":"Entrega el Carnaval por completo",
"4n5":"Todos los cables del Mar Rojo están cortados, y también el salto a Egipto. Consigue igualmente que Marsella hable con Singapur: rodeando África, por tierra, o dando la vuelta al planeta por el otro lado.",
"4n6":"Todos los IX los gestiona DE-KICKS",
"4n7":"Los eyeballs crecen un 50 % más rápido",
"4n8":"Fibra hasta el sótano",
"4n9":"Peering estilo Gangnam",
"4na":"Resiste 20 inundaciones, 5 de ellas de más de 1 Tbps: cada objetivo al 97 % o más, nadie más afectado",
"4nb":"Honolulú, en medio del Pacífico. Los cables entre las Américas, Asia y Australia son tan largos que una onda en ellos solo lleva 400G u 800G. Corta la luz en una isla, empiézala de nuevo, y cada salto se acorta y se acelera. Empiezas con equipo de 1.6T desbloqueado.",
"4nc":"Acento mesoatlántico",
"4nd":"Solo Spätzle-IX",
"4ne":"Orden y Progreso",
"4nf":"Ponta Delgada, en las Azores, a medio camino por el Atlántico. De Florida a España es demasiado largo para una onda de 1.6T: en línea recta, lleva 1.2T. Aterriza en las islas intermedias, empieza la luz de nuevo, y cada salto va a 1.6T o más. De Lisboa a Lagos el 1.6T llega de un tirón, pero caro: las Canarias salen más baratas. Empiezas con equipo de 1.6T desbloqueado.",
"4ng":"Puertos en 15 intercambios IX.brrr que tu backbone une a São Paulo, uno de ellos en Manaos, y 200 Gbps servidos",
"4nh":"Llega al 50 % de internet y sirve 300 Gbps",
"4ni":"Crisis del Mar Rojo",
"4nj":"Río desde cero. El Carnaval empieza en 90 días y quiere 400 Gbps durante cinco días seguidos. Todo el mundo está mirando.",
"4nk":"<b>Modo sandbox</b><br>Mil millones de dólares y todo desbloqueado. Caos: {chaos}. Construye el internet que siempre quisiste, y ten a mano una excavadora de repuesto.",
"4nl":"<b>Modo sandbox</b><br>Mil millones de dólares, todos los desbloqueos y nada se rompe nunca. Construye el internet que siempre quisiste.",
"4nm":"São Paulo. Brasil es un continente: cuarenta intercambios IX.brrr, miles de provedores, y el Amazonas entre tú y el norte.",
"4nn":"Seúl, donde paga quien envía. Cada Gbps que un carrier entrega en Corea te cuesta una tasa de «paga quien envía» además de la factura de tránsito, los tres operadores históricos solo hablan por un PNI de pago, el gigabit doméstico se vende al precio de un bibimbap y los usuarios coreanos notan cada milisegundo. El tránsito en Tokio es barato, si tus clientes aguantan el viaje.",
"4no":"{g} Gbps servidos, Seúl bien servida ({q} %), 99 % de alcance y beneficio mensual",
"4np":"Temporada de tiburones: los cortes submarinos son el doble de probables",
"4nq":"Empieza en Ciudad de Panamá. Nada cruza el Tapón del Darién por tierra, y los Andes se interponen en todo lo demás.",
"4nr":"Empieza en Stuttgart, donde nadie vende tránsito. Llega a internet solo por peering, PNIs, cachés y tu propia fibra. Sin tránsito en ningún sitio, nunca.",
"4ns":"Empieza con solo $100k",
"4nt":"Sídney, 2013. El Toilet Paper Group tendió su propia fibra hasta los sótanos de los edificios, y la red nacional gritó que escogía lo mejor. Te toca: sáltate la Nearly Broadband Network, paga el gravamen y llega primero.",
"4nu":"Tallin, donde nadie vende tránsito: tu internet está al otro lado del agua. Los barcos arrastran sus anclas sobre los cables del Báltico tres veces más a menudo de lo normal.",
"4nv":"La riña de Cogentle",
