"4pw":"<b>El {p} del tráfico de {city} viene de {to}: {ms} ms de ida y vuelta.</b> Los usuarios coreanos notan todo lo que pase de 8 ms, y por encima de 40 ms la banda ancha cuenta como mal servicio. Sirve más desde Seúl: peering, cachés y PNIs aquí, o tránsito local si aguantas la tasa de «paga quien envía».",
