"h0":"De Portugal a Lagos, con paradas en Dakar, Abiyán y Acra. Solo piensa en África Occidental.",
"h1":"De Portugal al sureste de EE. UU. vía Bermudas. Significa nube en portugués, y es propiedad de una.",
"h2":"Cruce rápido del Pacífico con parada para picar algo.",
"h3":"De Sajalín a Kamchatka y Magadán, tendido en 2016 para que la península dejara de depender de los satélites.",
"h4":"De Samoa a Tahití pasando por las Islas Cook. Infusionado despacio.",
"h5":"De Escocia a Islandia vía Shetland y las Feroe. Más ovejas que paquetes.",
"h6":"De Seattle directo a Shanghái, Seúl y Taipé.",
"h7":"Salto corto por el Mar del Norte. Una odisea no es.",
"h8":"Saltos cortos bajo el Mar Báltico. Cada barco que pasa parece encontrarlo.",
"h9":"Singapur, Tailandia, Hong Kong, Manila y Japón, con tan pocos desvíos como permite el mar de la China Meridional.",
"ha":"De Singapur a Sídney vía Perth, los días que funciona.",
"hb":"De Singapur a Tokio vía Vietnam y Hong Kong.",
"hc":"Sexto de una larga serie. De Europa a la India y a Singapur.",
"hd":"Atlántico Sur, fresco y seguro de sí mismo.",
"he":"Del sudeste asiático a Japón, con tentempiés.",
"hf":"De Stavanger a los Países Bajos e Inglaterra pasando por todas las plataformas petrolíferas del Mar del Norte. Los operarios ven muchísimo fútbol.",
"hg":"De Estocolmo a Helsinki por el archipiélago. Ligero, rápido y justo donde los barcos echan el ancla.",
"hh":"Directo a través del Atlántico Sur, de Fortaleza a Camerún. Sin paradas, sin islas, sin excusas.",
"hi":"Directo de São Paulo a Nueva York, saltándose la horquilla de Miami.",
"hj":"Sídney, Melbourne, Adelaida y Perth por mar, para que tus paquetes nunca tengan que cruzar el Nullarbor.",
"hk":"De Sídney a Auckland con holgura de sobra.",
"hl":"De Sídney a Honolulu, y ni un metro más. Llegar al continente es tu problema.",
"hm":"De Sídney a Numea. Ojalá fuera un supercontinente.",
"hn":"De Sídney a Papúa Nueva Guinea y las Islas Salomón. Tararea mientras trabaja.",
"ho":"De Sídney a Tokio vía Guam, dando vueltas y vueltas desde 2001.",
"hp":"De Tahití a Hawái, pescando ancho de banda.",
"hq":"Tarawa, Nauru y Pohnpei en un cable nuevo, que se une al antiguo hasta Guam.",
"hr":"De Tenerife a la península española. Mientras siga cantando, todo va bien.",
"hs":"La cadena de islas de las Bahamas, con un ramal al sur hasta Haití y mucho drama en medio.",
"ht":"El cable que conectó a África Oriental, de Durban a Yibuti y luego a Bombay. Aún cuenta la historia en cada fiesta.",
"hu":"Los Emiratos, Omán y Pakistán en un cablecito ligero.",
"hv":"El primer cable de Sudamérica a Oceanía. 14 000 km de vidrio muy solitario.",
"hw":"La primera fibra submarina del Ártico estadounidense: de Nome a Utqiaġvik, y luego por el North Slope hasta Anchorage. El hielo marino mantiene alejados a los barcos de reparación la mitad del año.",
"hx":"La línea propia del operador histórico hacia el sur: por tierra hasta Lucena y luego bajo el mar hasta Cebú. Sigue llamando cada noche.",
"hy":"El cable más nuevo de Sudáfrica a Madagascar, Reunión y Mauricio, compartido por las telcos de las propias islas.",
