"hyper_az.hit_cert":"Un certificado de {zone}, en {city}, caducó a las 3 de la madrugada y se llevó ese edificio. Respondieron las otras zonas. La región sirve el {p}.",
"hyper_az.hit_cooling":"La refrigeración de {zone}, en {city}, se rindió. Ese edificio se apagó solo; los demás asumieron su carga. La región sirve el {p}.",
"hyper_az.hit_squirrel":"Una ardilla provocó un cortocircuito en el cuadro eléctrico de {zone}, en {city}. Ese edificio se quedó a oscuras; los demás ni parpadearon. La región sirve el {p}. La ardilla está bien.",
"hyper_az.hit_ups":"La sala de baterías de {zone}, en {city}, suspendió la prueba mensual fallando de verdad. Un edificio se reinició, despacio; el resto siguió al {p}.",
