"hyper_dir.intro_ai":"🧠 <b>Los laboratorios de IA tienen tu número.</b> Quieren semanas de entrenamiento entre dos de tus regiones. Millones si llega a tiempo, la mitad si llega tarde.",
"hyper_dir.intro_ddos":"🧨 <b>Las botnets han encontrado tu dirección.</b> De vez en cuando alguien inunda a un tenant. Puertos de sobra y un backbone ancho lo aguantan.",
"hyper_dir.intro_fail":"🦍 <b>Dos regiones, así que ya puede caer una región entera.</b> Sus usuarios pasan a la réplica. Mantén bajo el atraso y ancho el backbone: este es el examen.",
"hyper_dir.intro_freeze":"🎮 <b>Tu estudio de videojuegos prepara un lanzamiento.</b> Los días de lanzamiento multiplican su tráfico y congelan tu red: construye antes de la congelación.",
"hyper_dir.intro_inc":"☁️ <b>Ya eres lo bastante grande para romperte a lo cloud.</b> Certificados caducados, tormentas de replicación, la Route 66 perdiendo un punto. Cada una trae su botón para arreglarla.",
"hyper_dir.intro_law":"🏛️ <b>Los reguladores han descubierto las nubes.</b> Las leyes llegan con preaviso: construye donde piden, o paga.",
"hyper_dir.intro_pev":"⚡ <b>Ahora la energía tiene sus días.</b> Olas de calor y crisis energéticas golpean continentes enteros: las facturas suben y las enfriadoras sudan. Si una red está a punto de saltar, te avisan con un día de antelación.",
"hyper_dir.intro_rv":"🥊 <b>Las nubes rivales se han fijado en ti.</b> Pujarán por tus tenants, cortejarán a los descontentos en la renovación y de vez en cuando empezarán una guerra de precios.",
