"hyper_fail.msg_cert":"Un certificado caducó en {city} a las 3 de la madrugada y se llevó toda la región. El aviso fue a un buzón que nadie lee.",
"hyper_fail.msg_cooling":"La refrigeración de {city} se rindió en plena ola de calor. Los servidores se apagaron antes de convertirse en barbacoa.",
