"hyper_fail.msg_ups":"La sala de baterías de {city} suspendió su prueba mensual fallando de verdad. Toda la región se reinició, despacio.",
"hyper_fail.news_cats":"ÚLTIMA HORA: millones de fotos de gatos perdidas al caer la región cloud de {city}",
"hyper_fail.news_save":"TITULAR: jugadores pierden partidas de 400 horas al hundirse la región de {city}",
"hyper_fail.news_spreadsheet":"ESCÁNDALO: desaparece la única copia de LA hoja de cálculo de contabilidad en la caída de {city}",
"hyper_fail.news_wedding":"TRAGEDIA: vídeos de boda perdidos para siempre al caer la región cloud de {city}",
