"hyper_freeze.fail_lag":"{game} salió con 900 ms de lag. Los speedrunners ahora hacen speed-walking. A {name} no le hace gracia.",
"hyper_freeze.fail_meme":"El lanzamiento de {game} se cayó tan fuerte que fue meme antes que juego. {name} está «revisando socios».",
"hyper_freeze.fail_queue":"El lanzamiento de {game} de {name}: cuatro millones de jugadores en la cola de inicio de sesión, entraron tres. Las reseñas lo llaman «un simulador de sala de espera».",
"hyper_freeze.fail_refund":"Las peticiones de reembolso de {game} superan a sus jugadores. El CEO de {name} publicó tu página de estado.",
"hyper_inc.cert_cal":"El recordatorio para renovar el certificado de la puerta de entrada en {city} estaba en el calendario de alguien que se fue en 2023. Los usuarios ven un aviso rojo y se van a otro sitio.",
"hyper_inc.cert_exp":"El certificado TLS de tu puerta de entrada en {city} caducó a medianoche. Los navegadores muestran una página roja aterradora; los usuarios dan la vuelta hacia otra puerta, si la hay.",
"hyper_inc.dns_ttl":"Alguien puso todos los TTL de Route 66 a cero \"para que los cambios salgan antes\". Los servidores de nombres se fundieron; {n} tenants con DNS están más o menos desconectados.",
"hyper_inc.dns_zone":"Route 66 está caído: un archivo de zona perdió su punto final. {n} tenants con DNS llaman a la vez. Era el DNS. Siempre es el DNS.",
"hyper_inc.melt_queue":"{game} salió y la cola de inicio de sesión de {name} llegó a la Luna. La región de {city} está en llamas y sirve menos hasta que acabe el lanzamiento.",
"hyper_inc.melt_retry":"Todos los jugadores de {game} pulsaron reintentar a la vez. La tormenta de reintentos se llevó la región de {city}; {name} culpa a la nube, tú al botón.",
"hyper_inc.pow_crane":"Una grúa de la obra de al lado se encontró con la subestación que alimenta {city}. {util} está en ello; mientras tanto la región sirve la mitad.",
"hyper_inc.pow_diesel":"{util} perdió un transformador en {city}. Los generadores arrancaron y luego se secaron: el presupuesto de gasóleo se fue en la fiesta de Navidad.",
"hyper_inc.pow_kite":"Un festival de cometas se enredó en las líneas eléctricas hacia {city}. {util} dice que era una cometa muy bonita. La región sirve la mitad.",
"hyper_inc.press_hn":"Un hilo sobre ello llega a 3.000 comentarios; 2.000 dicen que lo habrían autoalojado.",
"hyper_inc.press_postmortem":"Tu postmortem promete no culpar a nadie. El becario no está tan seguro.",
"hyper_inc.press_status":"Tu página de estado se quedó en verde todo el rato. Nadie se lo cree.",
"hyper_inc.press_trend":"\"¿Se cayó la nube?\" es tendencia mundial.",
"hyper_inc.storm_dedupe":"El servicio de deduplicación de {city} fue deduplicado. La replicación hacia {b} reenvía todo, {x} veces lo normal.",
"hyper_inc.storm_flag":"Un push de configuración cambió un flag en {city}: la región cree que su réplica en {b} lo olvidó todo, y se lo reenvía todo, {x} veces más.",
"hyper_inc.storm_yaml":"Alguien indentó una línea de YAML en {city}. Ahora la replicación hacia {b} copia cada objeto {x} veces, por si acaso.",
