"hyper_ops.o_az":"Dividir las regiones en zonas",
"hyper_ops.o_az_d":"Una región que tuvo averías locales (un cuelgue, un apagón, un dedazo en un edificio) recibe otra zona de disponibilidad, donde el nivel, los megavatios y la ley lo permitan. Una por turno.",
"hyper_ops.o_drill":"Simulacros de failover",
"hyper_ops.o_drill_d":"Un simulacro para el par de regiones probado hace más tiempo (primero los nunca probados), de uno en uno, nunca justo antes de un congelamiento por lanzamiento.",
"hyper_ops.o_fund":"Responder a las protestas",
"hyper_ops.o_fund_d":"Una protesta que los fondos comunitarios ganarían, hasta el precio de abajo, los recibe hasta ganarla. La buena voluntad no mueve tráfico.",
"hyper_ops.o_rg":"Vigilar las regiones",
"hyper_ops.o_rg_desc":"Una región en el límite o por encima sube al siguiente nivel, como mucho una al mes y solo a un nivel que alcanzaste hace dos niveles, si los megavatios y la ley lo permiten y el mes sigue en beneficio; si falta energía, se pide pronto a la eléctrica. Si no, una nota en el informe.",
"hyper_ops.o_wave":"Waves para el atraso",
"hyper_ops.o_wave_desc":"Un par de regiones cuyo atraso de replicación pasa del límite recibe una wave alquilada entre ambas, la más pequeña que lleve lo que faltó: una por turno, luego una semana para vaciarlo. Su precio mensual cuenta contra el presupuesto y nunca lleva el mes a pérdidas.",
