"lj":"Terreno barato, energía barata y veranos de 48 °C. Los hiperescaladores la adoran. Los enfriadores no.",
"lk":"Energía barata, aire seco y un número sorprendente de centros de datos muy tranquilos.",
"ll":"Viento barato, aire frío y un campus hiperescala en la pradera: aquí los servidores de Microsnoft superan en número a la gente.",
"lm":"Más barato que la vecina Singapur. Los constructores de centros de datos lo notaron, y la red eléctrica también.",
"ln":"La capital de Chukotka, más cerca de Alaska que de Moscú. Su cable va a Kamchatka; ninguno cruza el estrecho de Bering.",
"lo":"El puerto caribeño de Colombia, con el carnaval más grande después del de Río, donde los cables llegan a tierra antes de la larga subida a Bogotá.",
"lp":"Costa Rica funciona casi por completo con energía renovable, así que tus racks son verdes. El bosque nuboso de al lado es más verde.",
"lq":"Encrucijada de cables entre Europa, Asia y África. Algunas apps de voz están bloqueadas, y la factura del aire acondicionado es legendaria.",
"lr":"El único cable de Cuba viene de Venezuela y llega al otro extremo de la isla, no desde Florida a 150 km.",
"ls":"La costa oeste de Dinamarca, donde llegan a tierra los cables transatlánticos y los parques eólicos del mar del Norte.",
"lt":"Sol del desierto, energía barata y toda la región china de una nube extranjera, operada por un socio local.",
"lu":"Todo digital, e-residencia para cualquiera, y cables bálticos sobre los que los barcos arrastran el ancla una y otra vez.",
"lv":"Dunas, buggies y el rincón de Brasil más cercano a África.",
"lw":"Cada uno de los tres operadores de Malta tiene su propio cable a Sicilia, y el grande de Asia para aquí camino de Marsella.",
"lx":"El hub de África Oriental. Los cables aterrizan en Mombasa, y el dinero móvil lo mueve todo.",
"ly":"La capital de Etiopía a 2400 m, sin costa propia: todo sube desde Yibuti. El café es el mejor del mapa.",
"lz":"La encrucijada de Europa. Muchas redes, muchas salchichas.",
"m":"Encargos hechos",
"m0":"La nueva puerta atlántica de Europa. Los cables a Brasil, África y EE. UU. aterrizan costa abajo, en Sines.",
"m1":"Todos los grandes operadores iraníes llegan al mundo a través de una sola red estatal: un único cuello de botella para noventa millones de personas.",
"m2":"Todos los cables entre las Américas pasan apretados por aquí. Nada cruza el Tapón del Darién por tierra, así que Sudamérica siempre está a un salto submarino.",
"m3":"Todos los hiperescaladores construyen aquí una región. El terreno es barato y el biryani excelente.",
"m4":"La sede europea de todos los hiperescaladores, sobre todo por razones fiscales. La red eléctrica está nerviosa.",
"m5":"Lejos de todo. Cada paquete aquí tiene un largo viaje de vuelta a casa.",
"m6":"Tierras de cultivo junto al lago Míchigan, convertidas en un gigavatio de IA.",
"m7":"Fibra rápida al este y al oeste, y un cable submarino muy nervioso hacia Alemania.",
"m8":"La capital de Fiyi y encrucijada del Pacífico Sur. Aquí paran los cables entre EE. UU., Australia y Nueva Zelanda, y otros menores siguen a Tonga y Samoa.",
"m9":"Cinco cables llegan a Libreville, entre ellos la línea propia del operador histórico marroquí, directa hasta Casablanca.",
"ma":"Cuatro cables llegan a San Cristóbal, y en su exchange están los tres ISP de la isla: una pequeña federación que hace peering mejor que muchos países grandes.",
