"ops.mood_annie":"Annie respondió tres preguntas antes de que las hicieras, desde la mesa más cercana.",
"ops.mood_broke":"{name} ya tiene la lista de la compra para cuando llegue el presupuesto del mes que viene.",
"ops.mood_busy":"{name} ha tenido una semana movida y va por la tercera bebida energética.",
"ops.mood_kevin":"Kevin dice que en 2001 todo estaba más tranquilo. No lo estaba.",
"ops.mood_new":"{name} ha encontrado la cafetera y la CLI, en ese orden. Cuando quieras.",
"ops.mood_oops":"{name} va con mucho cuidado hoy. Que nadie mencione las descripciones de las interfaces.",
"ops.mood_outage":"{name} está mirando las gráficas de la avería y recargando la página de estado. Mucho.",
"ops.mood_quiet":"{name} lee RFCs tranquilamente. Las gráficas están planas, como debe ser.",
"ops.mood_snag":"{name} se topó con algo raro, pausó esa orden y te dejó un pósit.",
"ops.mood_tracy":"Tracy va por el tercer salto de un traceroute, con solo un asterisco de momento.",
"ops.o_caches":"Aceptar cachés gratis",
"ops.o_caches_d":"Montar cada caché gratis que ofrezca una red, en cuanto su tráfico en esa ciudad pase un umbral.",
"ops.o_decom":"Retirar enlaces paralelos pequeños",
"ops.o_decom_d":"En cuanto funcione un enlace mayor entre dos ciudades, devolver las waves pequeñas que ya no hacen falta. Nunca una que un cliente alquile o necesite.",
"ops.o_fabric":"Ampliar tus exchanges",
"ops.o_fabric_d":"Mejorar el fabric de un exchange tuyo cuando su tráfico supera el margen, o cuando no quedan plazas y una red espera para unirse. Un fabric más grande lleva más tráfico y admite más miembros que pagan.",
"ops.o_ix":"Peering en cada IX",
"ops.o_ix_d":"Cada semana: unirse a los route servers y pedir peering a cada miembro dispuesto en cada uno de tus puertos de exchange.",
"ops.o_optics":"Encender más fibra",
"ops.o_optics_d":"Añadir ópticas a la fibra oscura que va caliente y encender la fibra nueva el día que te la entregan.",
"ops.o_optup":"Mejorar el transporte óptico",
"ops.o_optup_d":"En la fibra que está llena y va caliente, o de la que los compradores del mercado de capacidad quieren más de lo que puede vender, sube el sistema de línea un tamaño o cambia los canales más pequeños por ópticas más grandes (las viejas van a la estantería). Elige un sistema de línea y cada fibra con uno más pequeño sube a ese. Cambiar el sistema de línea deja la fibra sin servicio un día, así que solo donde el tráfico puede rodearla y ningún cliente va por ella, uno por noche.",
"ops.o_pie":"Mantener las cortezas llenas",
"ops.o_pie_d":"Reserva lanzamientos para que tus cortezas sigan llenas cuando las tartas viejas se desgastan: tartas del almacén de la fábrica, la primera plataforma libre, nunca un vuelo de prueba. Cada uno cuesta lo que cobra la pestaña Cortezas.",
"ops.o_pni":"PNI con los grandes",
"ops.o_pni_d":"Cada semana: pedir un PNI a cada red dispuesta que envíe suficiente tráfico en tus POPs, con el tamaño mínimo de cada red.",
"ops.o_ports":"Margen en puertos de peering",
"ops.o_ports_d":"Mantener los puertos PNI e IX por encima de un múltiplo del tráfico de hoy: un puerto único en un POP con varios routers recibe un segundo en LAG, todos los demás suben un tamaño de puerto.",
"ops.o_repair":"Acelerar reparaciones",
"ops.o_repair_d":"Pagar la reparación urgente de cada caída que la tenga, mientras dure el presupuesto.",
"ops.o_routers":"Routers por delante",
"ops.o_routers_desc":"Añadir un router, o pasar a la siguiente generación donde un segundo router lleve el tráfico, cuando la carga o los puertos pasen de un nivel. Elige un modelo y cada POP con uno más pequeño se cambia a ese, primero el más cargado, dentro del presupuesto.",
"ops.o_transit":"Margen de tránsito",
"ops.o_transit_d":"Mantener el tránsito de cada POP por encima de un múltiplo de su pico de 30 días: un miembro LAG más o un tamaño de puerto mayor.",
"ops.o_waveup":"Waves alquiladas más grandes",
"ops.o_waveup_d":"Subir una wave alquilada a un tamaño mayor cuando va al límite, salvo que en esa ruta haya o se esté construyendo fibra oscura propia.",
