"optx.l_d":"Planificadores, empalmadores y un veterano de cables submarinos que ya ha visto cada error una vez. Cuatro rutas a la vez, y casi nunca se equivocan.",
"optx.l_n":"Departamento de Fotónica",
"optx.m_d":"Un equipo óptico de verdad, con herramienta de planificación y furgoneta. Dos rutas a la vez.",
"optx.m_dark":"Alguien se equivocó al teclear una configuración: {where} está a oscuras hasta mañana.",
"optx.m_n":"El Escuadrón Lambda",
"optx.m_over":"Roca donde el estudio decía arena en {where}: la obra cuesta {cost} más.",
"optx.m_slip":"Los permisos para {where} tardaron más: la obra se retrasa {n} días.",
"optx.s_d":"Dos ingenieros y una empalmadora. Planifican una ruta a la vez y no revisan nada dos veces.",
"optx.s_n":"Una empalmadora y una hoja de cálculo",
"oq":"El hub de cables del Mar Rojo de Arabia Saudí. Cada vez más cables entre Europa, África y Asia paran aquí en lugar de en Egipto.",
"or":"La capital de Escocia. Los cables del Mar del Norte a Noruega y las Feroe aterrizan costa arriba.",
"os":"Seis redes en la tabla de rutas global, y un gateway que lleva la mayor parte del tráfico del norte.",
"ot":"Pequeño, rico y muy bien conectado. Su única frontera terrestre es con Arabia Saudí.",
"ou":"Parte de la banda ancha doméstica más rápida del planeta, y el mercado de peering más raro. Con el «sender pays», los tres grandes ISP cobran por cada gigabit que se les entrega, y el tránsito aquí es de los más caros del mundo.",
"ov":"La costa este de Sudáfrica: surf, curry y la playa donde aterrizan los cables del Índico.",
"ow":"El mayor mercado de Sudamérica y hogar de IX.brrr: gestionado por una organización sin ánimo de lucro, precios públicos, y casi todo el mundo está en él.",
"own_cable.a_fishing_fleet_is_trawling_exactly":"Una flota pesquera está faenando justo donde necesitas tender.",
"own_cable.a_whale_has_parked_on_the":"Una ballena se ha aparcado en la ruta y no se mueve.",
"own_cable.storm_season_the_ship_is_sheltering":"Temporada de tormentas. El barco se refugia en puerto, jugando a las cartas.",
"own_cable.the_cable_ship_s_coffee_machine":"Se rompió la cafetera del barco cablero. Nadie trabaja sin café.",
"own_cable.the_crew_fished_out_somebody_else":"La tripulación pescó por error el cable de otro y tiene que volver a ponerlo.",
"own_cable.the_seabed_survey_found_an_old":"El estudio del lecho marino encontró una vieja mina marina. Un pequeño desvío, muy cuidadoso.",
"ox":"Reglas de internet soberano: cada POP necesita una caja del gobierno en el rack, el vídeo de Goggle va estrangulado y el cortafuegos nacional hace simulacros.",
"oy":"Startups, techno y un número sorprendente de centros de datos en antiguas cervecerías.",
"oz":"Aquí aterrizan cables submarinos hacia África y Asia.",
"p":"{city} se queda a oscuras",
"p0":"El primer cable de Surinam llega a tierra en Totness, dos horas al oeste por la costa, y sigue hasta Guyana y Trinidad.",
"p1":"La costa oeste de Suecia, a medio camino entre Oslo y Copenhague: por aquí pasa la fibra entre Suecia y Noruega.",
"p2":"La ciudad federal de Suiza gobierna desde aquí y hace peering desde Zúrich, a una hora por la vía.",
"p3":"Tahití, en la Polinesia Francesa. Un cable sube al norte hasta Hawái, y el nuevo de Chile a Australia para aquí: el trampolín entre Sudamérica y Oceanía.",
"p4":"Tango, asado y una multitud muy fiel de ISP locales.",
"p5":"La ciudad más grande de Tanzania y la puerta al mar de media docena de países sin costa propia.",
"p6":"El primer cable de Tarawa llegó en 2026: dos mil kilómetros hasta Nauru y Pohnpei, pagados por tres gobiernos amigos.",
"p7":"La capital pesquera de las Aleutianas. La fibra llegó en 2023; antes, satélites y paciencia.",
"p8":"Las Azores, en medio del Atlántico. Los cables de Florida a Lisboa y España paran aquí, así que un POP parte la travesía y cada mitad lleva más. Las vacas superan a los servidores.",
"p9":"La capital de las Bahamas, a un salto de Florida. Casi todos los cables hacia el sur paran aquí por el camino.",
"pa":"La ciudad más grande al norte del círculo polar ártico. El cable ruso Polar Express iba a salir de aquí hacia el este; solo el primer tramo está en el agua. Tiende el tuyo.",
"pb":"El extremo sur del país, con líneas eléctricas construidas para una fundición de aluminio. Alguien construye un campus de IA de 280 MW en un potrero a las afueras, así que los cables vienen en camino. Probablemente.",
"pc":"El fondo del mapa. Aire fresco, hidroeléctrica barata y todo el estrecho de Bass entre tú y el continente.",
"pd":"La capital de negocios del África occidental francófona, con torres de cristal sobre una laguna y cinco cables en la bahía.",
"pe":"Las Canarias, a un salto de Lisboa y Marruecos. Casi todos los cables por la costa oeste de África paran aquí, lo que convierte el largo tramo a Lagos en dos más cortos.",
"peering_desk.closed_desc":"Se rechaza toda solicitud de peering, y no hay route servers. Los clientes oyen que eres difícil de contactar, así que te llaman menos.",
"peering_desk.open_desc":"Toda red que lo pide recibe una sesión, y los route servers funcionan.",
"peering_desk.open_to_all":"Abierto a todos",
"peering_desk.selective_desc":"Las redes pequeñas del intercambio y los recién llegados con PeeringDB al día reciben una sesión; el resto se rechaza en silencio. Sin route servers: solicita las redes que quieras en cada intercambio.",
"pf":"La capital, que construye campus de IA a escala de gigavatios. Los datos de usuarios saudíes tienen que quedarse en el Reino, y cada POP necesita una licencia de telecomunicaciones local.",
"pg":"La capital está aquí; el internet, a treinta kilómetros, en Cotonou, donde llegan los cables y funciona el exchange.",
"ph":"La capital de Acre, un estado que los brasileños bromean que no existe. Tus traceroutes dicen lo contrario.",
"pi":"La capital de las Islas Marshall, un anillo de coral a dos metros sobre el mar. Un cable a Guam, y cada paquete lo sabe.",
