"pie.fp_3am":"Publico a las 3 de la mañana porque dormir es un protocolo obsoleto. Nuestras tartas son un 40 % más ricas que el trimestre pasado.",
"pie.fp_astro":"Los astrónomos dicen que nuestras tartas se cuelan en sus telescopios. ¿Han probado a mirar entre ellas?",
