"pj":"El exchange de la capital es pequeño: el concurrido de Honduras está en San Pedro Sula, la ciudad de las fábricas del norte.",
"pk":"La capital. Dinero de IA soberana y centros de datos enormes. Dentro de los EAU solo los dos operadores con licencia pueden tender fibra.",
"pl":"La capital escribe las reglas con las que funciona internet y deja los servidores al lado: los centros de datos están a media hora, en Ashburn, así que la ciudad en sí es un mercado pequeño con usuarios muy importantes.",
"pm":"El Caspio no tiene salida al océano, así que el tráfico de Bakú sale por tierra, sobre todo hacia el oeste por Georgia.",
"pn":"La ciudad de la eterna primavera, con escaleras mecánicas al aire libre por las laderas y una escena de startups muy activa.",
"pnis.a_new_region_is_coming_online":"Pronto se pondrá en marcha una región nueva. Lleva poniéndose en marcha pronto desde 2019.",
