"pv":"El gateway de media Asia Central: las redes tayikas, turcomanas y afganas compran todas a través de Taskent.",
"pw":"El centro geográfico de Sudamérica, y una de las ciudades más calurosas de Brasil. Los enfriadores nunca libran.",
"px":"El centro geográfico de EE. UU. Los centros de datos están en antiguas minas de caliza bajo tierra: temperatura estable, sin tornados, y alguien sigue encontrando los zapatos de Dorothy.",
"py":"El gobierno se mudó colina arriba a Gitega en 2019; el exchange y los centros de datos se quedaron en Buyumbura.",
"pz":"El puerto, el puente y la mayoría de los centros de datos del país. El alquiler es la verdadera latencia.",
"q":"A {city} le faltan {g}",
"q0":"La sede de gobierno más alta de la Tierra, a 3600 m. Los trabajadores van en teleférico, y parte de la fibra también.",
"q1":"El largo camino a Johannesburgo: el tráfico de Yuba recorre miles de kilómetros antes de encontrarse con la mayor parte de internet.",
"q2":"La capital de Maldivas, a un metro sobre el mar y escala de los cables de la India al Golfo y Singapur.",
"q3":"El centro de todas partes: sin mar, sin cable, solo fibra por la autopista y una vieja estación de telégrafo.",
"q4":"La gran ciudad más aislada de la Tierra. Asia está más cerca que Sídney.",
"q5":"El hub del Norte, con su propio intercambio y tomas de aire acondicionado muy húmedas. Los cables a Irlanda y Dinamarca llegan a tierra costa arriba.",
"q6":"El pueblo más al norte de Estados Unidos, al que llega la primera fibra submarina del Ártico estadounidense.",
"q7":"La capital de los Territorios del Noroeste, al final de la fibra del valle del Mackenzie, tendida a lo largo del río hasta la costa ártica.",
"q8":"La vieja puerta de Europa del Este. Los paquetes aún hacen una reverencia educada al pasar.",
"q9":"La única capital del noreste lejos del mar. Famosamente calurosa, con tormentas eléctricas que mantienen ocupados a los protectores contra sobretensiones.",
"qa":"La puerta del Pacífico. Los Andes se interponen entre ella y todo lo demás, y el suelo tiembla de vez en cuando.",
"qb":"La segunda ciudad de Filipinas, solo alcanzable por cable nacional. Los tifones pasan por aquí rumbo al norte.",
"qc":"La puerta de las praderas entre Vancouver y el resto de Canadá. Un chinook derrite la nieve en una tarde, y luego vuelve a nevar.",
"qd":"El hub del Rin-Ruhr: más centros de datos neutrales que Hamburgo o Múnich, y a una hora de la frontera holandesa, así que la fibra a Ámsterdam es corta y barata. Pide aquí una Altbier, nunca una Kölsch.",
"qe":"La capital de las Seychelles, en Mahé: 115 islas, tortugas gigantes y dos cables al continente.",
"qf":"La capital de las Islas Salomón, en Guadalcanal. El cable a Sídney llegó hace pocos años; antes todo era satélite. La electricidad es menos fiable que el cable.",
"qg":"El carrier hotel del Sureste. El aeropuerto más concurrido, el peering más concurrido al sur de Ashburn.",
"qh":"Aquí llegan a tierra los cables transatlánticos, en la costa vasca. El punto de intercambio está en Madrid, así que casi todo el tráfico se va tierra adentro.",
"qi":"La Venecia de Brasil, toda puentes y ríos, con uno de los mayores parques tecnológicos del país en su viejo puerto.",
"qj":"Todo el país es una sola red que anuncia un puñado de rutas, y los hogares normales no están conectados.",
"qk":"Todo el país en un cable: un ramal de ACE, que llegó en 2011 y que comparten todos los operadores.",
"ql":"La capital del Yukón, en un único tendido largo de fibra por la autopista de Alaska: un corte al sur de la ciudad y todo el territorio espera.",
"qm":"Celebra la mayor fiesta de São João del mundo: un mes entero de forró cada junio. También ciudad universitaria llena de ingenieros.",
"qn":"El primer cable de Timor Oriental se encendió en julio de 2026: seiscientos kilómetros hasta el North-West Cable System de Australia.",
"qo":"Diminuta, tropical y la ciudad australiana más cercana a Asia. Los nuevos cables a Singapur y Yakarta aterrizan aquí, junto a los cocodrilos.",
"qp":"Tonga cuelga de un solo cable desde Fiyi. En 2022 un volcán submarino lo cortó y el país estuvo semanas sin conexión.",
"qq":"La capital de Trinidad, en el extremo sur de la cadena de islas y a pocos kilómetros de Venezuela.",
"qr":"Doce mil personas y su primer cable, que llegó en agosto de 2025 de camino de Tarawa a Pohnpei.",
"qs":"A veinte minutos de todo, salvo de cualquier otro sitio.",
"qt":"Ciudades gemelas, un exchange y pasarelas entre los edificios: Minneapolis también hace peering aquí, y en enero nadie sale a empalmar una fibra.",
"qu":"A dos horas al norte de Estocolmo, una región de nube y una famosa cabra de paja.",
"qv":"Dos millones de personas en medio de la selva, con una zona franca industrial. La fibra sigue los ríos, y cuando se rompe, el equipo de reparación va en barco.",
"qw":"Dos exchanges rivales, uno en la universidad técnica y otro comercial, y casi todas las redes eslovacas están en los dos.",
"qx":"Tifones, terremotos y muchísima gente muy conectada.",
"qy":"Los ingenieros de red ucranianos mantuvieron internet en marcha durante apagones y cosas mucho peores. Generadores, fibra de repuesto y redundancia en todo son lo normal aquí, y la escena del peering es famosamente dura.",
"qz":"Universidades, biotecnología y un carrier hotel que ha sobrevivido a la mayoría de sus operadores.",
"r":"Cerrado",
"r0":"Uruguay: fibra en casi todos los hogares, un portátil para cada escolar y una telco estatal que gestiona casi todo.",
"r1":"Muy conectada y mal atendida por el mar: al menos uno de sus cables submarinos está roto en cualquier momento.",
"r2":"La capital de Virginia, donde los cables transatlánticos de Virginia Beach llegan tierra adentro a un exchange neutral: una entrada a Europa más tranquila que Ashburn.",
"r3":"El calor residual va directo al spa de al lado.",
"r4":"Las llanuras del oeste de Texas, terreno barato y un gigavatio de entrenamiento de IA creciendo encima.",
"r5":"Cuando cortaron su único cable en 2018, Mauritania quedó casi totalmente offline durante dos días.",
"r6":"Cuando llegó el cable en 2025, todo el país tuvo internet gratis durante un día para celebrarlo.",
"r7":"Donde se encuentran Brasil, Argentina y Paraguay, junto a cataratas gigantes y una presa hidroeléctrica aún mayor. La energía es barata; el papeleo aduanero, no.",
"r8":"Donde llegan a tierra los cables de África Oriental, y luego suben en tren hasta Nairobi.",
"r9":"Donde llegan a tierra el viento del mar del Norte y la energía submarina, un campus de nube tras el dique.",
"ra":"Donde de verdad aterrizan los cables de Sudamérica. Europa, África y EE. UU. llegan a tierra aquí y luego bajan por un largo backhaul al sur.",
"rb":"Donde aterrizan los cables atlánticos hacia el sur de África. Pingüinos en la playa, cortes programados en la red.",
"rc":"Casas blancas que trepan desde el Mediterráneo. Los cables van al norte hacia Marsella, y buena parte del tráfico también.",
"rd":"Parques eólicos y aire frío al norte de Pekín: los campus de nube de la capital.",
"re":"Energía eólica, terreno barato y el Misuri: el campus de nube del corazón del país.",
