"sa":"Dar de baja varios POPs…",
"sales.auto_ceo":"{name} firma las ofertas que tu red puede servir hoy, una prueba al día. También rechaza las que quedan bajo tu mínimo, aunque de vez en cuando ya había dado la mano.",
"sales.auto_eng":"{name} firma las ofertas que tu red puede servir hoy, después de probar cada una en la red (una al día), y rechaza las que pagan menos que tu mínimo.",
"sales.auto_shark":"{name} firma cada oferta en cuanto llega, con promesas y todo, mientras puedas pagar la comisión, y rechaza las que pagan menos que tu mínimo.",
"sales.ceo_d":"Gratis, y convencido. Cada par de meses firma un trato enorme en el campo de golf con un 30 % de descuento, a menudo con una promesa que nadie comprobó, y de vez en cuando firma una oferta que tú rechazaste. Tiene opiniones. No se le puede despedir.",
"sales.ceo_n":"El CEO, que vende mejor que nadie",
"sales.ceo_s":"el CEO",
"sales.ceo_say_airport":"Acabo de aterrizar. No he firmado nada, pero el Wi-Fi de la sala VIP me dio muy buena espina.",
"sales.ceo_say_blockchain":"¿Hemos pensado en poner la tabla de rutas en una blockchain?",
"sales.ceo_say_golf":"Los mejores tratos se cierran en el hoyo nueve. El NOC debería jugar más al golf.",
"sales.ceo_say_mbps":"¿Por qué vendemos gigabits? Megabits suena a más.",
"sales.ceo_say_napkin":"He calculado el próximo trato en una servilleta. Ingeniería puede resolver los detalles.",
"sales.ceo_say_synergy":"No vendemos ancho de banda, vendemos sinergia. Ponedlo en la web.",
"sales.ceo_sky":"En órbita: una de cada dos partidas de golf la juega con el Fundador, por el trato en órbita más grande que quepa, con un 30 % de descuento. Los mercados nerviosos le cuestan: precios más bajos en órbita, y nada de golf cuando están muy nerviosos.",
"sales.eng_d":"Era ingeniero de redes y ahora tiene la acreditación de cada NOG. Te apunta a todas (la entrada la pagas tú), trae muchos tratos pequeños y medianos pero nunca los grandes de verdad, y solo vende lo que la red puede hacer, así que los clientes se quedan. Los nerds adoran a Dave. Negocia fatal.",
"sales.eng_n":"El ingeniero convertido en vendedroide",
"sales.eng_s":"Dave",
"sales.eng_sky":"En órbita: solo vende donde la antena de aterrizaje tiene margen de sobra, y esos clientes se quedan como los nerds.",
"sales.ren_ceo":"{name} responde a la renegociación de un cliente tres días después de que empiece, en el campo de golf: más descuento del pedido a cambio de un contrato el doble de largo, un sí rápido o una pelea tras la que el cliente se va.",
"sales.ren_ceo_fight":"{name} le dijo a {cust} que con él nadie regatea. Se han ido.",
"sales.ren_ceo_yes":"{name} le dijo que sí a {cust} antes de que nadie pudiera comprobarlo: {price}/mes.",
"sales.ren_eng":"{name} responde a la renegociación de un cliente tres días después de que empiece. Los clientes frikis reciben una tarde con los diagramas de la red y suelen renovar a precio de mercado; los demás reciben el descuento que pidieron. Nadie se va.",
"sales.ren_eng_cave":"{name} le dio a {cust} el descuento que pidió: {price}/mes. Se quedan.",
"sales.ren_eng_tech":"{name} pasó una tarde enseñando la red a los ingenieros de {cust}. Renuevan a {price}/mes, sin descuento.",
"sales.ren_mid":"{name} y {cust} se encontraron a medio camino: {price}/mes.",
"sales.ren_shark":"{name} responde a la renegociación de un cliente tres días después de que empiece, y no regala nada: la mayoría renueva al precio antiguo, a menudo con una promesa nueva, y te cobra un mes de lo que te ahorró. Algunos se van, sobre todo los frikis.",
"sales.ren_shark_walk":"{name} se puso duro con {cust}, y se fueron.",
"sales.shark_d":"Consigue los tratos más grandes a un cuarto más, y se lleva un mes de cada trato de comisión. Vende de más: la mitad llega con una promesa que tu red aún no cumple, y esos clientes se van antes. Ignora a los nerds: nada de clientes técnicos ni de reuniones, y los equipos de peering te piden un cuarto más de tráfico. Gana casi todas las negociaciones.",
"sales.shark_n":"El tiburón",
"sales.shark_s":"Chad",
"sales.shark_sky":"En órbita: llama primero a aerolíneas y cruceros, al tamaño más grande y a un cuarto más, y a la mitad les promete un cielo lleno antes de que lo tengas. Refunfuñan hasta que lo tienes.",
"sb":"Arrastra desde este router hasta cualquier ciudad del mapa para tender un enlace nuevo. Dos caminos a cada POP significan que una retroexcavadora no te deja sin conexión.",
"sc":"Todos los puertos están ocupados. Añade un router o cambia a un modelo con más puertos antes de conectar nada nuevo.",
"sd":"Todo está en un solo edificio. Mueve algunos uplinks a la otra sede desde las pestañas Tránsito y Peering.",
