"sp":"Funciona con tu propia fibra, así que la Nearly Broadband Network no recibe nada. El gobierno aun así cobra un gravamen del {pct}.",
"specialist.cable_broker":"Bróker de cables",
"specialist.cable_broker_desc":"Tiende fibra en tierra y cables bajo el mar desde el primer día, ilumínalos y vende la capacidad a otros operadores. Objetivos propios; gana Barón del Vidrio: tus propios cables llegan a {n} continentes mientras los operadores te pagan {m} al mes. Todo lo demás se desbloquea por nivel, como siempre.",
"specialist.global_backbone":"Backbone global",
"specialist.low_latency_boutique":"Boutique de baja latencia",
"specialist.spotted_your_broadband_in_a_one":"Vieron tu banda ancha en {a}, una de las grandes ciudades de usuarios.",
"specialist.spotted_your_cap_of_dark_fiber":"Vieron tus {cap} de fibra oscura iluminada entre {a} y {b}.",
"specialist.spotted_your_ms_ms_a_b_path":"Vieron tu camino {a}–{b} de {ms} ms.",
"specialist.spotted_your_two_diverse_paths_a":"Vieron tus dos caminos diversos entre {a} y {b}.",
"specialist.the_classic_game_grow_everywhere_and":"El juego clásico: crece en todas partes, los clientes siguen tu nivel y Tier 1 es la victoria.",
"specialist.trading_firms_and_other_latency_customers":"Las firmas de trading y otros clientes de latencia llaman más a menudo y pagan un {p}% más. Gana Velocidad de la luz: supera la latencia alquilada más rápida en {r} rutas financieras con tu propia fibra mientras {c} clientes de latencia te pagan. Tier 1 sigue contando.",
