"supply_chain.chip_shortage_every_router_vendor_is":"<b>¡Escasez de chips!</b><br>Todos los fabricantes de routers esperan los mismos chips. Los routers nuevos y sus mejoras cuestan un 40 % más durante {n} días. Plazo de entrega: «sí».",
"supply_chain.every_cable_ship_is_booked":"<b>Todos los barcos cableros están reservados.</b><br>Los hiperescaladores han contratado todos los barcos cableros y cuadrillas de zanjas del planeta. La fibra y los cables nuevos cuestan un 30 % más durante {n} días.",
"supply_chain.laser_shortage_the_factory_that":"<b>¡Escasez de láseres!</b><br>Se inundó la fábrica que hace los láseres de la mitad de las ópticas del mundo. Las ópticas cuestan un 50 % más durante {n} días. Los repuestos de tu estante acaban de ser la mejor inversión de tu vida.",
