"tr":"Cuando está activo, anuncia el objetivo de forma más específica, así que las inundaciones llegan a su propia entrada de {g} en lugar de a tus puertos, y las limpia. El tráfico limpio vuelve por tu backbone. También desbloquea contratos de protección DDoS.",
