"tv":"Peering remoto en el IX",
"tw":"Ahora mismo {city} es un solo edificio. Un corte de luz, un fallo del aire acondicionado o un limpiador con aspiradora deja a toda la ciudad a oscuras, y un segundo router no ayuda con eso. Un segundo centro de datos al otro lado de la ciudad, unido por tu propio anillo metropolitano, mantiene en pie la mitad del POP.",
