"ua":"El modelo define tu interfaz más rápida y cuánto puede reenviar este POP. Más routers añaden capacidad y sobreviven a las caídas.",
"ub":"La Nearly Broadband Network se queda con el {pct} para la última milla.",
"uc":"La jaula estándar tiene sitio para {n} routers. Cada uno más necesita una ampliación: instalarlo cuesta un 50% más y pagas {mo}/mes extra por espacio y energía.",
"ud":"Este chasis tarda una eternidad en arrancar: las caídas duran más, y cambiar el único router de aquí lleva 3 días. Un segundo router lo disimula.",
